exercises.solutionCode:
int sumValues(Map<String, int> data) {
  return data.values.fold(0, (sum, value) => sum + value);
}

void main() {
  print(sumValues({'a': 1, 'b': 2, 'c': 3}));
  print(sumValues({}));
}
